// CBSE 11 English Core, ch01 Reading Comprehension, Note Making and Summary: question bank.
// Every passage, data set, note-making brief and name below is SOYL's own writing (passage_origin 'soyl-original').
// No passage is taken or adapted from any book, newspaper, website, sample paper or past paper. Numbers in tables
// are invented and labelled illustrative data; general facts (Sundarbans, millets, Rani ki Vav, harvest festivals) are
// stated at the level of common knowledge.
// School pattern (exam_notes): reading 26 = two unseen passages (10 + 8), note making 5, summary 3. SOYL models the
// chapter test on the class-default blueprints: 4-mark case-based passage sets, 5-mark note-making and reading longs,
// 3-mark summaries (wl 40-60 for a summary of about 50 words), objective items on the conventions.
// Topics: t01 unseen passages (factual, descriptive, literary, case-based) · t02 note making · t03 summary writing.
import { Q, mcq, fb, short, tf, ar, match, ord, long, caseQ, child } from './lib.mjs';

const S2 = (o) => short({ marks: 2, wl: [30, 50], time: 150, ...o });
const L5 = (o) => long({ marks: 5, ...o });
const S3 = (o) => short({ marks: 3, wl: [50, 80], time: 210, ...o });
const SUM = (o) => short({ marks: 3, wl: [40, 60], time: 270, ...o });
const SC_PT = [['The point or inference that answers the question', 1], ['Support from the passage, in own words', 1]];
const SC_JUDGE = [['A clear judgement', 1], ['Reason or evidence from the passage, in own words', 1]];
const SC_SUM = [
  ['Main ideas: all key points of the passage covered, none of the examples copied', 1.5],
  ['Brevity: about 50 words (40 to 60 accepted), no copying of whole sentences', 0.5],
  ['Expression: own words, correct grammar and spelling, no personal opinion', 1],
];
const SC_NOTES = [
  ['Title that sums up the passage', 1],
  ['Headings and sub-headings that group the points logically, with numbering or indentation', 2],
  ['Points complete, accurate and in short form (no full sentences)', 1],
  ['Abbreviations used sensibly, with a key', 1],
];

// ================================================================ case-based passage sets (4 marks each)
Q('cs_commute', caseQ({
  t: 1, d: 3, c: 'analysis', origin: 'soyl-original',
  stem: 'Read the report extract on how students reach school and study the table (illustrative data). Answer all parts.',
  passage: `The Environment Club of a school for Classes 9 to 12 surveyed 240 students on how they reach school each morning. In its report the club concludes that "most students depend on the school bus" and asks the principal to buy more buses. Its findings are shown below.

| Way of reaching school | Students |
|---|---|
| School bus | 96 |
| On foot | 60 |
| Cycle | 24 |
| Dropped by parents | 60 |
| Total | 240 |`,
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'application', stem: 'What fraction of the surveyed students come to school on foot or by cycle?', opts: ['seven in twenty (35 per cent)', 'one in four (25 per cent)', 'one in ten (10 per cent)', 'two in five (40 per cent)'], sol: '60 + 24 = 84 students, and 84 out of 240 is 35 per cent. One in four counts the walkers alone.' })),
    child('b', tf({ t: 1, d: 3, c: 'analysis', stem: 'True or false: the table supports the club\'s conclusion that most students depend on the school bus.', ans: false, sol: 'The bus carries 96 of 240 students, which is 40 per cent. It is the biggest group but not a majority.' })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', marks: 2, wl: [25, 50], stem: '**(i)** Using figures from the table, suggest one recommendation the club could make other than buying more buses.', model: 'The club could ask for safer cycle lanes and stands. Only 24 of 240 students cycle, one in ten, while 60 are dropped by parents, so some of those students living nearby might cycle instead and ease the traffic at the gate.', sol: 'Any recommendation tied to a figure: cycling (24), walking (60) or parent drop-off (60).', scheme: SC_PT }, ), [
      S2({ t: 1, d: 3, c: 'analysis', marks: 2, wl: [25, 50], stem: '**(ii)** Why might the 60 students dropped by parents matter to the club\'s aim? Answer with figures.', model: 'They are a quarter of all surveyed students (60 of 240), as many as those who walk. Each drop-off puts one more vehicle near the gate, so the club could encourage car-sharing or cycling for those living nearby.', sol: 'Point: a quarter of the students; support: one reason linked to traffic or the club\'s aim.', scheme: SC_PT }),
    ]),
  ],
}));

Q('cs_flowers', caseQ({
  t: 1, d: 2, c: 'application', origin: 'soyl-original',
  stem: 'Read the descriptive passage **The Flower Lane at Dawn** and answer all parts.',
  passage: `Before the first bus has started, the flower lane is already awake. Lorries unload mountains of marigold, and the air is heavy with the smell of jasmine and wet jute. Vendors sit cross-legged between sacks, threading garlands with quick fingers, never once looking down at their hands. A boy of about ten drags a bucket across the lane, sprinkling water over the orange heaps so that they will not wilt before the temples open. Nobody hurries, yet nothing waits. By the time the sky turns pale, the best flowers have been bought, and the lane begins to empty as quietly as it filled.`,
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'application', stem: 'Which impression of the market does the passage mainly create?', opts: ['busy, skilled and quietly organised', 'confused and noisy', 'lazy and slow-moving', 'dangerous and overcrowded'], sol: 'The workers are busy but unhurried, and the closing lines describe the lane emptying quietly: order, not chaos.' })),
    child('b', fb({ t: 1, d: 2, c: 'understanding', stem: 'Find a word in the passage that means *to droop because of a lack of water*: ___', acc: [['wilt']], sol: 'The boy sprinkles the marigolds so that they will not **wilt**.' })),
    child('c', mcq({ t: 1, d: 3, c: 'application', stem: 'The sentence about nobody hurrying while nothing waits suggests that the work is…', opts: ['done calmly but without delay', 'done carelessly', 'never finished', 'left until the last moment'], sol: 'Calm movement plus nothing left waiting points to practised, steady efficiency.' })),
    child('d', mcq({ t: 1, d: 2, c: 'application', stem: 'What is the writer\'s attitude towards the vendors?', opts: ['quietly admiring', 'mocking', 'worried', 'bored'], sol: 'The detail about their skill and calm is warm and approving; no word criticises or mocks them.' })),
  ],
}));

Q('cs_trophy', caseQ({
  t: 1, d: 3, c: 'analysis', origin: 'soyl-original',
  stem: 'Read the passage from a short story, *The Trophy*, written by SOYL, and answer all parts.',
  passage: `Sunita had rehearsed the speech all week, yet when Mr Menon rose to hand her the trophy, the words scattered like startled pigeons. She looked at the hall: her mother in the third row, pretending not to cry; Divya, her old rival, applauding more loudly than anyone; and Mr Menon himself, whose gruff "Hurry up" in the first term had once reduced her to tears. She remembered the evening she had nearly left the debating club, and how a worn notebook had been pushed across the staffroom table without a word. "Say what you feel," he muttered now, so softly that only she heard. She took a breath, and the first honest sentence came.`,
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'understanding', stem: 'The comparison of her words to startled pigeons suggests that…', opts: ['her prepared words suddenly flew out of her mind', 'her speech was about birds', 'she was fond of pigeons', 'the hall was full of birds'], sol: 'The simile pictures words scattering in fright: Sunita is overcome and loses her rehearsed lines.' })),
    child('b', mcq({ t: 1, d: 3, c: 'analysis', stem: 'What can be inferred from the notebook being pushed across the table without a word?', opts: ['Mr Menon cared about her progress but showed it quietly', 'Mr Menon wanted the notebook back', 'Mr Menon was angry with her', 'Mr Menon wished to close the club'], sol: 'A silent gift at the moment she nearly quit shows concern without speech, which fits his gruff manner.' })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', marks: 2, wl: [25, 50], stem: '**(i)** Why do you think the writer mentions that Divya applauded more loudly than anyone?', model: 'It shows that Divya, a rival, is generous and sincerely glad for Sunita. It also deepens Sunita\'s emotion, since support from a rival is unexpected, and it suggests the competition left no bitterness behind.', sol: 'Inference about Divya or about Sunita\'s feelings, supported by the detail.', scheme: SC_PT }), [
      S2({ t: 1, d: 3, c: 'analysis', marks: 2, wl: [25, 50], stem: '**(ii)** What does the last sentence suggest about the way Sunita will now speak?', model: 'It suggests that she will speak simply and truthfully instead of delivering the rehearsed speech. Mr Menon\'s whisper reminds her that honest feeling matters more than polished words, and her nervousness gives way to sincerity.', sol: 'Inference: honest, unscripted speech; support from the whisper or from the word honest.', scheme: SC_PT }),
    ]),
  ],
}));

Q('cs_millet', caseQ({
  t: 2, d: 3, c: 'application', origin: 'soyl-original',
  stem: 'Read the passage **Millets Return** and answer the note-making questions that follow.',
  passage: `Millets are small-seeded grasses such as jowar, bajra and ragi, grown across India for thousands of years. They thrive in dry regions and poor soil and need far less water than rice. Farmers like them because a crop is ready in about three months and survives weak rains. Millets are also rich in fibre and minerals; ragi, for example, is a good source of calcium. After rice and wheat took over the plate in the twentieth century, millets were pushed aside as poor people's food. Today, health-conscious urban families and agricultural planners are bringing them back, and the United Nations named 2023 the International Year of Millets.`,
  parts: [
    child('a', mcq({ t: 2, d: 3, c: 'application', stem: 'Which is the most suitable title for notes on this passage?', opts: ['Millets: Why They Are Making a Comeback', 'Rice and Wheat in India', 'Ragi and Calcium', 'Farming in Dry Regions'], sol: 'The title must cover the whole passage: what millets offer and why they are returning. The others cover one detail only.' })),
    child('b', mcq({ t: 2, d: 2, c: 'application', stem: 'Under which heading would the points *needs little water* and *ready in about three months* fit best?', opts: ['Advantages for farmers', 'Health benefits', 'Decline in the twentieth century', 'Revival today'], sol: 'Both points are reasons that make millets attractive to those who grow them.' })),
    child('c', fb({ t: 2, d: 1, c: 'recall', stem: 'Complete the note line: *Millets rich in fibre and minerals, e.g. ragi: high in* ___', acc: [['calcium']], sol: 'The passage names **calcium** as what ragi is a good source of.' })),
    child('d', mcq({ t: 2, d: 3, c: 'application', stem: 'Which is the best note for the fall of millets?', opts: ['20th c.: rice and wheat replaced millets; seen as poor man\'s food', 'Rice and wheat took over the plate in the twentieth century and millets were pushed aside', 'millets', 'Rice and wheat are good grains'], sol: 'A good note keeps the century, the cause and the stigma in a short point; one option copies a full sentence, another is too thin to be useful.' })),
  ],
}));

Q('cs_stepwell', caseQ({
  t: 3, d: 3, c: 'application', origin: 'soyl-original',
  stem: 'Read the passage **Steps to the Water** and answer the summary questions that follow.',
  passage: `In western India, where rivers run dry for months, communities once built stepwells: deep wells reached by long flights of steps. In Gujarat they are called vavs. A villager could walk down to the water, whose level rose and fell with the seasons, and the cool chambers beside the steps gave travellers a place to rest. Some, such as Rani ki Vav at Patan, are richly carved and are now World Heritage Sites. With piped water and borewells, stepwells fell into disuse, and many filled with rubbish. In recent years, local groups and heritage bodies have cleaned and restored several of them, and a few now serve again as places that collect rainwater.`,
  parts: [
    child('a', mcq({ t: 3, d: 3, c: 'analysis', stem: 'Which one-sentence summary best covers the whole passage?', opts: ['Stepwells, built to reach water in dry western India, fell into neglect with modern water supply but are now being restored.', 'Rani ki Vav at Patan is richly carved and is a World Heritage Site.', 'Stepwells were beautiful and should be opened to tourists everywhere.', 'In Gujarat, stepwells are called vavs, and villagers rested in cool chambers beside the steps.'], sol: 'It carries purpose, decline and revival. The others keep one detail, add an opinion, or stop after the first half.' })),
    child('b', mcq({ t: 3, d: 2, c: 'application', stem: 'Which detail is the best one to leave out of a summary of about 40 words?', opts: ['the carving of Rani ki Vav as an example', 'stepwells were built to reach water', 'stepwells fell into disuse', 'several are now being restored'], sol: 'An example illustrates a main point but is not itself a main point; the other three are the passage\'s main stages.' })),
    child('c', tf({ t: 3, d: 2, c: 'understanding', stem: 'True or false: a summary may add the summary-writer\'s own view that all stepwells should be turned into tourist sites.', ans: false, sol: 'A summary reports only the ideas of the original writer, never the summariser\'s opinion.' })),
    child('d', fb({ t: 3, d: 2, c: 'understanding', stem: 'Complete the summary line: *Stepwells, once vital in dry western India, fell into disuse but are now being* ___', acc: [['restored', 'revived', 'cleaned and restored']], sol: 'The passage ends with several stepwells being cleaned and **restored**, so the summary line must close on that idea.' })),
  ],
}));

// ================================================================ MCQs reserved for deck check slides (not used in tests)
Q('dk_skim', mcq({ t: 1, d: 1, c: 'understanding', stem: 'You have thirty seconds to find out what an unseen passage is mainly about. Which way of reading helps most?', opts: ['reading the title, the opening and closing lines and the first line of each paragraph', 'reading every word slowly from the start', 'looking only for numbers and dates', 'reading only the options of the questions'], sol: 'This is skimming: it collects the gist by sampling the places where main ideas sit.' }));
Q('dk_infer', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Aman looked at the clock again and again, tapped his pen on the desk and stood up twice before the bell rang. What is the most reasonable inference?', opts: ['He was impatient for the period to end', 'He was seriously ill', 'He disliked the teacher', 'He had lost his pen'], sol: 'Repeated clock-watching and fidgeting point to impatience; illness, dislike and a lost pen have no clue behind them.' }));
Q('dk_vocab', mcq({ t: 1, d: 2, c: 'understanding', stem: 'The old well was so parched in May that even the frogs had left, and villagers carried water from a river three kilometres away. In this sentence, *parched* means…', opts: ['completely dry', 'very deep', 'full of weeds', 'recently dug'], sol: 'The frogs leaving and water carried from far away show that the well had no water: the general sense of the sentence gives the meaning.' }));
Q('dk_tone', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Every evening the grandmother polishes the brass lamp her own grandmother once lit, smiling as she remembers festival nights when the whole lane glowed. The tone of the sentence is…', opts: ['nostalgic', 'sarcastic', 'apprehensive', 'objective'], sol: 'She fondly remembers glowing festival nights from the past, which is the mark of a nostalgic tone.' }));
Q('dk_heading', mcq({ t: 2, d: 1, c: 'understanding', stem: 'A passage lists three ways a school can save water: mending leaks, using buckets instead of hoses and collecting rainwater. Which heading covers all three?', opts: ['Ways of saving water in school', 'Water in nature', 'Problems caused by leaking taps', 'Rainwater harvesting'], sol: 'A heading must name the whole group. The last option names only one of the three points.' }));
Q('dk_abbr', mcq({ t: 2, d: 1, c: 'understanding', stem: 'Which of these abbreviations can be used in notes without an entry in the key?', opts: ['e.g.', 'stdts', 'gvt-sch', 'wtr'], sol: 'Only standard, widely known abbreviations can stand alone; the other forms are personal shorthand that need a key.' }));
Q('dk_subpoint', mcq({ t: 2, d: 1, c: 'understanding', stem: 'Notes on cycling have the heading *Benefits of cycling*. Which of these belongs beneath it as a sub-point?', opts: ['improves fitness', 'Safety rules for cyclists', 'History of the bicycle', 'Types of cycles'], sol: 'A sub-point must be one of the benefits; the other options would be headings of their own.' }));
Q('dk_summary', mcq({ t: 3, d: 2, c: 'understanding', stem: 'A paragraph explains that tea needs rain, warm weather and hilly slopes, gives Assam as an example, and ends with the remark that tea is a favourite drink of many. In a 40-word summary, priority should go to…', opts: ['the three conditions tea needs', 'the Assam example', 'the writer\'s closing remark', 'the taste of tea'], sol: 'Conditions are the paragraph\'s main idea; the example and the closing remark are supporting or incidental.' }));

// ================================================================ MCQs, t01 unseen passages
Q('m_main_idea', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Read: *Last year the town library began lending seeds as well as books. Members borrow a packet, grow the plants and return seeds from their harvest. Within a season the seed shelf had become the busiest corner of the library, and neighbours who had never met began swapping tips.* The main idea of the passage is that…', opts: ['a library found a new way to bring a community together', 'seeds grow best near libraries', 'books are no longer popular', 'neighbours dislike gardening'], sol: 'Every sentence supports one idea: a seed-lending service that connects people. The other options are not stated or are contradicted.' }));
Q('m_purpose', mcq({ t: 1, d: 3, c: 'analysis', stem: 'A writer describes an umbrella-repairer outside a railway station. Asked why he does not sell new umbrellas, he replies that a new umbrella is only bought, but an old one remembers every rain it has stood in. Why does the writer include his reply?', opts: ['to show that he values the memories attached to old things', 'to prove that new umbrellas are poor in quality', 'to advertise his shop', 'to explain how umbrellas are repaired'], sol: 'The reply is figurative and personal; it reveals his attitude to old objects rather than giving facts about quality or repair.' }));
Q('m_inference_closed', mcq({ t: 1, d: 2, c: 'understanding', stem: 'The village school\'s notice board has had no new notice since June. A sheet covers the headmaster\'s chair, and the playground grass is knee-high. What can be inferred?', opts: ['The school has been shut for a long time', 'The headmaster is unkind', 'The students are on a picnic', 'The school has moved to a new building'], sol: 'Three clues of long disuse (no notices, covered chair, tall grass) point to a closed school; the other options have no clue.' }));
Q('m_not_stated', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Read: *Cheetahs are the fastest land animals, but they can keep up their top speed for only a short distance. After a sprint they must rest, and many chases fail. This is why a cheetah prefers to stalk close to its prey before it runs.* Which of these is NOT stated in the passage?', opts: ['Cheetahs hunt only at night.', 'A cheetah needs rest after a sprint.', 'Many cheetah chases end without a catch.', 'Cheetahs stalk before running.'], sol: 'Nothing is said about the hours of hunting; the other three points are given directly.' }));
Q('m_tone_sarcasm', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Read: *The committee thanked the residents for their patience, a word the residents had stopped hearing with any meaning after the third year without piped water.* Two tones are plausible: appreciative and ironic. Which is right, and which detail decides it?', opts: ['ironic, because the writer says the word had lost its meaning for the residents', 'appreciative, because the committee thanked the residents', 'ironic, because the committee is mentioned', 'appreciative, because the word patience is positive'], sol: 'The thanks looks warm, but the detail that residents no longer hear the word with meaning shows the writer treating it as hollow. A tone must be proved by a detail, not by the surface word.' }));
Q('m_word_context', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Though the road was narrow and treacherous, the driver crossed it without a tremor, for he had driven it for twenty years. Here, *treacherous* means…', opts: ['full of hidden dangers', 'newly built', 'very crowded', 'pleasantly quiet'], sol: 'The word *though* sets the danger against the driver\'s calm, so the road must be risky.' }));
Q('m_phrase', mcq({ t: 1, d: 2, c: 'understanding', stem: 'After the third failed experiment, Ritu decided to go back to the drawing board. The phrase means that she decided to…', opts: ['start planning again from the beginning', 'draw a picture of the apparatus', 'give up science for good', 'ask the teacher to design the experiment'], sol: 'After repeated failure, going back to the drawing board means to rethink the plan from the start.' }));
Q('m_reference', mcq({ t: 1, d: 3, c: 'application', stem: 'In School P, 45 of 150 students cycle to school; in School Q, 60 of 250 do (illustrative data). A reporter writes that Q is the more cycling-friendly school because it has more cyclists. Which conclusion do the figures support?', opts: ['A larger share of students at School P cycle (30 per cent against 24 per cent), though Q has more cyclists.', 'Q has the larger share of cyclists because 60 is more than 45.', 'The two schools have the same share of cyclists.', 'The figures say nothing about cycling at either school.'], sol: '45 of 150 is 30 per cent and 60 of 250 is 24 per cent. Raw numbers mislead when the groups differ in size; compare shares.' }));
Q('m_data_comp', mcq({ t: 1, d: 3, c: 'application', stem: 'A library lent 120 books in January, 150 in February, 180 in March and 144 in April (illustrative data). Between which two consecutive months was the percentage rise largest?', opts: ['January to February', 'February to March', 'March to April', 'The rise was the same in every pair'], sol: 'January to February: 30 on 120 is 25 per cent. February to March: 30 on 150 is 20 per cent. March to April is a fall. Equal rises in number do not mean equal percentages.' }));
Q('m_fact_opinion', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which of these statements is a fact rather than an opinion?', opts: ['The canteen sold 320 samosas on Friday.', 'The canteen samosas are the best in the city.', 'Nobody should ever eat anything else for lunch.', 'The canteen should be rebuilt at once.'], sol: 'A fact can be checked against a record; the others judge or recommend.' }));

// ================================================================ MCQs, t02 note making
Q('m_notes_title', mcq({ t: 2, d: 3, c: 'understanding', stem: 'A passage explains that cyclones form over warm seas, hit the east coast of India more often than the west, and cause fewer deaths today because of early warnings and shelters. Which title suits notes on it best?', opts: ['Cyclones: Formation, Impact and Safety', 'The Indian Coast', 'Warm Seas', 'Why Shelters Are Built'], sol: 'A title should sum up the whole passage; the other options name only a place, a cause or a single measure.' }));
Q('m_notes_abbr_bad', mcq({ t: 2, d: 1, c: 'understanding', stem: 'Which of these abbreviations is unacceptable in notes because no reader could guess its meaning without a key?', opts: ['qzv for canal', 'govt. for government', 'approx. for approximately', 'e.g. for for example'], sol: 'An abbreviation should be standard or obviously related to the word; a random letter group is neither.' }));
Q('m_notes_indent', mcq({ t: 2, d: 1, c: 'recall', stem: 'In note making, a sub-heading is…', opts: ['a smaller group of points placed under a main heading', 'the title of the notes', 'the last line of the notes', 'the list of abbreviations'], sol: 'Notes work in levels: heading, then sub-heading, then points.' }));
Q('m_notes_pointform', mcq({ t: 2, d: 3, c: 'analysis', stem: 'A passage says that the canal silted up, so boats could no longer reach the market, so traders moved to the road, and the river port declined as a result. Which set of notes keeps the logic of the passage most faithfully?', opts: ['Canal silted → boats cannot reach market → traders shift to road → port declines', 'Canal; boats; market; traders; road; port', 'Port declined; canal silted; traders on road; boats stopped', 'Canal, market and port are all important to the town'], sol: 'The passage is a chain of causes and results. Only a version that keeps the links in order preserves it; a bare list or a scrambled order loses the reasoning.' }));
Q('m_notes_key', mcq({ t: 2, d: 1, c: 'recall', stem: 'Where should the key to the abbreviations you have used be written?', opts: ['at the end of the notes', 'in place of the title', 'before the first heading', 'inside the summary'], sol: 'The key follows the notes so a reader can look up each abbreviation.' }));
Q('m_notes_hierarchy', mcq({ t: 2, d: 3, c: 'application', stem: 'Notes under the heading *Causes of road accidents* read: 1.1 over-speeding; 1.2 drunk driving; 1.3 helmets reduce head injuries; 1.4 poor street lighting. Which point is out of place?', opts: ['1.3', '1.1', '1.2', '1.4'], sol: 'Helmets reduce injury; they are a remedy or effect, not a cause, so the point belongs under another heading.' }));

// ================================================================ MCQs, t03 summary writing
Q('m_sum_purpose', mcq({ t: 3, d: 1, c: 'recall', stem: 'A summary is…', opts: ['a short account of the main ideas of a passage in your own words', 'a copy of the first paragraph', 'a list of every example in the passage', 'your opinion about the passage'], sol: 'A summary shortens without changing the writer\'s ideas.' }));
Q('m_sum_best', mcq({ t: 3, d: 3, c: 'analysis', stem: 'Read: *Honeybees visit flowers for nectar and, without meaning to, carry pollen from plant to plant, which lets many crops form fruit. In some regions their numbers have fallen because of pesticides, loss of wild flowers and disease. Farmers there now sometimes pollinate by hand, which is slow and costly. Protecting hedgerows and using fewer chemicals are the simplest remedies.* Which is the best summary?', opts: ['Bees pollinate many crops, but pesticides, habitat loss and disease have reduced them, so protecting flowering habitat and cutting chemicals is the best remedy.', 'Bees collect nectar from flowers and carry pollen.', 'Honeybees visit flowers for nectar and carry pollen from plant to plant, which lets many crops form fruit, and in some regions their numbers have fallen.', 'Farmers are careless with chemicals and should be punished.'], sol: 'It is complete (role, decline, causes, remedy), in fresh words and free of opinion. The others are partial, copied or opinionated.' }));
Q('m_sum_include', mcq({ t: 3, d: 2, c: 'understanding', stem: 'A passage tells how a river town cleaned its ghats: a ban on plastic bags, weekend volunteer drives and fines for dumping. It includes a fisherman\'s joke about the old smell, and ends with the return of fish to the river. A summary of about 50 words should include…', opts: ['the three actions and the return of the fish', 'the fisherman\'s joke and the old smell', 'only the ban on plastic bags', 'the names of the volunteers'], sol: 'Main ideas are the actions and their result; the joke is colour and the names are detail.' }));
Q('m_sum_figure', mcq({ t: 3, d: 2, c: 'application', stem: 'A passage says that of 3,000 students, 2,400 now use the library every week. Which is the best way to carry this into a summary?', opts: ['Four in five students now use the library weekly.', '2,400 students.', 'Many students go.', '3,000 students use it.'], sol: '2,400 out of 3,000 is 80 per cent, which is four in five. A good summary compresses a figure without losing its meaning.' }));

// ================================================================ assertion-reason
Q('ar_notes_style', ar({ t: 2, d: 1, c: 'understanding', a: 'Notes are usually written in short phrases rather than full sentences.', r: 'Notes are meant to be read quickly and revised later.', verdict: 'both-true-explains', sol: 'Brevity serves quick reading and revision, so the reason explains the practice.' }));
Q('ar_subhead', ar({ t: 2, d: 2, c: 'understanding', a: 'In notes, a sub-heading is placed under a main heading.', r: 'A sub-heading must always be longer than the main heading.', verdict: 'A-true-R-false', sol: 'Sub-headings nest under headings, but no rule makes them longer; length is irrelevant.' }));
Q('ar_summary_opinion', ar({ t: 3, d: 2, c: 'understanding', a: 'A summary may include the summary-writer\'s own opinion on the topic.', r: 'A summary reports the ideas of the original writer.', verdict: 'A-false-R-true', sol: 'Because a summary reports the writer\'s ideas, a personal opinion has no place in it.' }));
Q('ar_cause', ar({ t: 1, d: 3, c: 'analysis', pre: 'In March a village library began a weekly story hour. Monthly loans were 30 in March and 90 in June, and the librarian said the story hour had caused the rise.\n\n', a: 'The figures prove that the story hour caused the rise in loans.', r: 'Loans tripled between March and June.', verdict: 'A-false-R-true', sol: 'The tripling is correct (30 to 90), but two things happening together do not prove cause: other reasons, such as exams or holidays, are possible.' }));
Q('ar_sarcasm', ar({ t: 1, d: 3, c: 'analysis', pre: 'Read: *How thoughtful of the airline to announce the delay only after we had waited four hours at the gate.*\n\n', a: 'The tone of the sentence is sarcastic.', r: 'It praises an action which, in the context, was late and unhelpful.', verdict: 'both-true-explains', sol: 'The praise word conflicts with the facts (announcing late), and that conflict is exactly what makes the tone sarcastic.' }));
Q('ar_trend', ar({ t: 1, d: 4, c: 'analysis', pre: 'A town\'s bus service carried 40,000 riders in 2022 and 46,000 in 2023. In the same period the number of buses rose from 50 to 52.\n\n', a: 'Ridership rose by a much larger percentage than the number of buses.', r: 'The number of riders per bus was higher in 2023 than in 2022.', verdict: 'both-true-not-explains', sol: 'Riders rose by 15 per cent (6,000 on 40,000) and buses by 4 per cent (2 on 50), so A is true. Riders per bus rose from 800 to about 885, so R is true; but R is a result of A, not its explanation.' }));

// ================================================================ true-false, fill-blank, match, ordering
Q('tf_abbr_key', tf({ t: 2, d: 1, c: 'recall', stem: 'True or false: an abbreviation of your own should be explained in a key at the end of your notes.', ans: true, sol: 'Without a key, a reader cannot be sure what a personal abbreviation stands for.' }));
Q('tf_sum_examples', tf({ t: 3, d: 2, c: 'understanding', stem: 'True or false: a 50-word summary should keep every example from the passage so that it is complete.', ans: false, sol: 'Examples illustrate points; a summary keeps the points and drops most examples.' }));
Q('tf_inference_clue', tf({ t: 1, d: 2, c: 'understanding', stem: 'True or false: an inference may rest on the reader\'s general opinion even when the passage offers no clue.', ans: false, sol: 'An inference must be supported by clues in the text; without a clue it is only a guess.' }));
Q('fb_pp', fb({ t: 1, d: 2, c: 'understanding', stem: 'A rise from 12 per cent to 18 per cent is a rise of six ___.', acc: [['percentage points', 'percentage point']], sol: 'A gap between two percentages is stated in percentage points.' }));
Q('fb_notes_parts', fb({ t: 2, d: 1, c: 'recall', stem: 'Notes begin with a ___ that sums up the passage and group their points under ___ and sub-headings.', acc: [['title'], ['headings', 'heading', 'main headings']], sol: 'A good set of notes has a title, headings and sub-headings, then points.' }));
Q('mt_abbr', match({ t: 2, d: 1, c: 'recall', stem: 'Match each abbreviation used in notes with its meaning.', pairs: [['govt.', 'government'], ['e.g.', 'for example'], ['esp.', 'especially'], ['w/o', 'without']], sol: 'These are standard abbreviations.' }));
Q('mt_tone', match({ t: 1, d: 2, c: 'understanding', stem: 'Match each tone word with the description that fits it.', pairs: [['apprehensive', 'worried about what may happen next'], ['sarcastic', 'saying the opposite of what is meant, in order to mock'], ['nostalgic', 'fondly remembering the past'], ['objective', 'reporting facts without showing personal feeling']], sol: 'Tone words name the writer\'s attitude.' }));
Q('od_notes_steps', ord({ t: 2, d: 2, c: 'understanding', stem: 'Arrange the steps of making notes in a sensible order.', items: ['Read the passage for its overall idea', 'Pick out the main points and sub-points', 'Group them under headings and sub-headings', 'Choose a title and abbreviations', 'Write the key to the abbreviations at the end'], sol: 'You must know what the passage says before choosing, grouping and labelling points; the key comes last.' }));

// ================================================================ short answers, 2 marks
Q('s2_inference', S2({ t: 1, d: 2, c: 'understanding', stem: 'At six in the morning Neha\'s hostel room still had its light on. Her desk was covered with sheets of rough work, and four empty tea mugs stood beside her books. What can you infer about Neha? Give one clue.', model: 'Neha has probably been studying all night, perhaps for an exam. The light is still on at six, her desk is covered with rough work, and the four mugs of tea suggest that she has been awake for hours, trying to stay alert.', sol: 'Inference: she studied through the night. Clues: light on, rough work, tea mugs.', scheme: SC_PT }));
Q('s2_tone_critical', S2({ t: 1, d: 3, c: 'analysis', stem: 'Read: *The minister described the flooded underpass as a temporary inconvenience. Residents, who had waded through chest-deep water for four days, were less relaxed about it.* Is the writer\'s attitude to the minister\'s description critical or approving? Support your answer with one detail.', model: 'Critical. The writer sets the minister\'s mild phrase against residents wading through chest-deep water for four days. The contrast shows that the phrase understates the problem and that the writer does not accept the minister\'s view.', sol: 'Judgement: critical. Support: the contrast between a mild phrase and four days in deep water.', scheme: SC_JUDGE }));
Q('s2_purpose_opening', S2({ t: 1, d: 3, c: 'analysis', stem: 'An essay on road safety opens with two short sentences: thirty children cross a junction every day, and not one of them has a signal. Why might the writer begin like this instead of with a table of statistics?', model: 'The two short sentences make the danger real and personal before any numbers appear. They hold the reader\'s attention at once and prepare the ground for the argument that the junction needs a signal.', sol: 'Purpose: to engage the reader and make the problem concrete; link to the argument.', scheme: SC_PT }));
Q('s2_vocab_clue', S2({ t: 1, d: 2, c: 'understanding', stem: 'Read: *The villagers were reluctant to leave their homes, but the rising river left them no choice.* What does *reluctant* mean? Which clue in the sentence helped you?', model: 'Reluctant means unwilling or hesitant. The word but signals a contrast: the villagers did not want to leave, yet the rising river gave them no choice, so the contrast with leaving is the clue.', sol: 'Meaning: unwilling. Clue: contrast signalled by *but*.', scheme: [['Correct meaning', 1], ['Clue identified and explained', 1]] }));
Q('s2_data_headline', S2({ t: 1, d: 3, c: 'application', stem: 'In 2022, 80 of the 200 Class 11 students of a school read a book for pleasure every week. In 2024, 90 of 250 did so (illustrative data). A headline says *Reading habit grows*. Is it fair? Use figures.', model: 'Not entirely. The number of readers rose from 80 to 90, but the group grew from 200 to 250 students, so the share fell from 40 per cent to 36 per cent, a drop of 4 percentage points. The headline uses only the number.', sol: '80 of 200 is 40 per cent; 90 of 250 is 36 per cent.', scheme: [['Compares shares: 40 per cent and 36 per cent', 1], ['Judges the headline correctly, with reason', 1]] }));
Q('s2_headings_group', S2({ t: 2, d: 3, c: 'application', stem: 'A passage on a school fair gives these points: stalls of handmade goods; money raised for the library; volunteers from Class 11; games for children; planning meetings in June; food stalls run by parents. Group them under two suitable headings.', model: 'Heading 1, Stalls and activities: handmade goods stalls, food stalls run by parents, games for children. Heading 2, Planning and purpose: planning meetings in June, volunteers from Class 11, money raised for the library.', sol: 'Two headings that each name their group; every point placed under the right one.', scheme: [['Two suitable headings', 1], ['All six points grouped correctly', 1]] }));
Q('s2_abbr_line', S2({ t: 2, d: 2, c: 'application', stem: 'Rewrite as one line of notes with at least two abbreviations, and give a key: *The government started a scheme in 2019 to give free books to students in rural areas.*', model: 'Notes line: Govt. scheme (2019): free bks to rural stdts. Key: Govt. = government; bks = books; stdts = students. The line keeps the date, the giver, the benefit and the group, and drops the filler words.', sol: 'A short line with at least two abbreviations, all explained in the key.', scheme: [['Short note line keeping all facts', 1], ['Abbreviations used and explained in a key', 1]] }));
Q('s2_subhead_diff', S2({ t: 2, d: 2, c: 'understanding', stem: 'Explain the difference between a heading and a sub-heading in notes, with one example.', model: 'A heading names a whole group of ideas, while a sub-heading names a smaller group inside it. For example, under the heading Advantages of cycling, the sub-headings could be Health and Cost, each with its own short points.', sol: 'Difference in level, plus an example.', scheme: [['Difference explained (whole group and smaller group)', 1], ['Suitable example', 1]] }));
Q('s2_sum_cut', S2({ t: 3, d: 2, c: 'application', stem: 'Read: *The Class 8 recycling drive began in July with 12 volunteers. Each week they collected waste paper, which a local firm bought at a fixed rate. Mohan designed the poster, which was painted in blue. By December the drive had raised enough to buy 40 books for the library and had cut the school\'s paper waste by almost half.* Name two details to leave out of a 40-word summary and say why.', model: 'Leave out Mohan\'s poster with its blue colour, and the number of volunteers at the start. They are small details which do not change the main idea: paper collected and sold funded library books and reduced waste.', sol: 'Two minor details named, with the reason that they are not main ideas.', scheme: [['Two minor details named', 1], ['Reason given: not main ideas', 1]] }));

// ================================================================ short answers, 3 marks
Q('s3_sum_kites', SUM({ t: 3, d: 3, c: 'application', stem: 'Read the passage and write a summary in about 50 words.\n\nEvery January, skies across many Indian cities fill with kites. The festival is joyful, but it has a darker side. Some flyers coat their thread with powdered glass to cut rivals\' strings, and the sharp, strong thread injures birds that fly into it, and riders of two-wheelers who meet it at neck level. Hospitals report more injuries every season, and bird-rescue groups treat many wounded birds. Several states have banned glass-coated and synthetic thread, and volunteers now tie protective wires on motorbikes. Experts say the real remedy is a change of habit: plain cotton thread, flying from open rooftops away from roads, and never leaving broken thread in trees.', model: 'Kite festivals bring joy, but glass-coated and synthetic thread injures birds and road users. Some states have banned such thread and volunteers fit protective wires on bikes. Experts say safer habits, such as cotton thread, flying away from roads and clearing broken thread, are the real remedy.', sol: 'Main ideas: the harm done, the bans and protections, the safer habits. Drop the details of hospitals and rescue groups.', scheme: SC_SUM }));
Q('s3_sum_lakes', SUM({ t: 3, d: 3, c: 'application', stem: 'Read the passage and write a summary in about 50 words.\n\nMany Indian cities were once dotted with lakes and tanks that stored monsoon rain and fed wells. As cities grew, builders filled many of them with soil to make land, and drains began to empty sewage into the rest. Without lakes, rain runs off the roads and floods low neighbourhoods, while groundwater falls because there is nothing to help the water soak into the ground. Some cities have started to restore their lakes, with citizens\' groups removing weeds and councils stopping sewage from entering. Early results are encouraging, though experts warn that restoration will fail unless the land around a lake is also protected.', model: 'Cities once had lakes that stored rain and fed wells, but many were filled for building or polluted by sewage, causing floods and falling groundwater. Citizens and councils are restoring some lakes, but experts warn this will fail unless the surrounding land is protected.', sol: 'Main ideas: the old role of lakes, their loss and its effects, restoration, the warning.', scheme: SC_SUM }));
Q('s3_sum_trim', SUM({ t: 3, d: 2, c: 'application', stem: 'A student wrote this 75-word draft as a summary of a notice about a colony\'s walking group. Rewrite it as a summary of about 50 words, keeping the main ideas.\n\nDaily morning walks, which many doctors recommend, have become popular in our colony. Last month, about thirty residents, including Mr Rao, who is 72, began walking in the park at six. They say they sleep better, feel cheerful and have more energy through the day. The park, which has a jogging track and a small garden, has a new guard. Residents hope that more neighbours will join, and they plan to hold a health camp.', model: 'About thirty residents of the colony have begun walking in the park at six every morning. They say they sleep better and feel more cheerful and energetic. They hope more neighbours will join and plan to hold a health camp.', sol: 'Keep who, what, the benefit and the plan; drop the age, the track and garden, and the new guard.', scheme: SC_SUM }));
Q('s3_notes_festivals', S3({ t: 2, d: 3, c: 'application', stem: 'Make notes on the passage in 50 to 80 words, with a title, headings and sub-headings, and abbreviations with a key.\n\nIndia marks the turning points of its farming year with festivals. Pongal, in Tamil Nadu, falls in January, when rice is boiled in new pots until it overflows. Baisakhi, in Punjab, comes in April, when the wheat is ready for cutting, and farmers celebrate with fairs and folk dances. Bohag Bihu in Assam also comes in April and marks the Assamese new year and the start of sowing. Onam, in Kerala, is observed in late summer and early autumn, with flower carpets and a feast.', model: 'Title: Farm Festivals of India\n\n1. Winter and spring\n   1.1 Pongal: TN, Jan; rice boiled in new pots till it overflows\n   1.2 Baisakhi: Punjab, Apr; wheat ready; fairs, folk dances\n   1.3 Bohag Bihu: Assam, Apr; new yr; sowing begins\n\n2. Late summer\n   2.1 Onam: Kerala, Aug-Sep; flower carpets, feast\n\nKey: TN = Tamil Nadu; yr = year', sol: 'Group by season or by region; short points; key for TN and yr.', scheme: [['Suitable title', 0.5], ['Two or more headings with sub-headings, logically grouped', 1], ['All four festivals with state and time, in short points', 1], ['Abbreviations with a key', 0.5]] }));
Q('s3_eval_assembly', S3({ t: 1, d: 4, c: 'evaluation', stem: 'A school magazine editorial says: *Our pass percentage rose from 82 to 91 after morning assemblies were shortened from 30 to 15 minutes. Shorter assemblies clearly produce better results, and every school should copy us.* Evaluate the strength of this argument in about 50 to 80 words.', model: 'The argument is weak. It shows two events happening together, shorter assemblies and a nine-point rise in the pass percentage, but gives no evidence that one caused the other. Better teaching, easier papers or a different batch of students could explain the rise. One school\'s experience also cannot justify the claim that every school should copy it.', sol: '82 to 91 is a rise of 9 percentage points. Judgement: the evidence shows correlation only.', scheme: [['Clear judgement: argument is weak or only partly convincing', 1], ['Correlation is not shown to be cause; other explanations suggested', 1], ['Comment on the sweeping generalisation, in own words', 1]] }));
Q('s3_data_library', S3({ t: 1, d: 4, c: 'analysis', stem: 'A library had 200 members in 2021 and lent 1,000 books; 250 members and 1,500 books in 2022; 300 members and 1,500 books in 2023 (illustrative data). A teacher says: *Borrowing has not grown since 2022, so members are losing interest.* Use figures to assess her claim in about 50 to 80 words.', model: 'Total loans stayed at 1,500, but membership rose from 250 to 300, so loans per member fell from 6 to 5 (1,500 divided by 250 is 6; 1,500 divided by 300 is 5). The teacher is partly right: each member borrows less. But the library gained members, so interest is not simply being lost.', sol: 'Loans per member: 2021 is 5, 2022 is 6, 2023 is 5.', scheme: [['Loans per member computed correctly for 2022 and 2023', 1], ['Conclusion that each member borrows less', 1], ['Balanced judgement using the rise in membership', 1]] }));

// ================================================================ long answers, 5 marks
Q('l_notes_rain', L5({ t: 2, d: 3, c: 'application', stem: `Make notes on the passage in 80 to 120 words, using a suitable title, headings and sub-headings, and abbreviations with a key.

A school roof is a large, free catchment for rain. On a roof of 800 square metres, a single heavy shower can send thousands of litres of water down the drains. Rainwater harvesting captures that water instead of wasting it. The simplest system has three parts: gutters along the roof edge, a pipe that carries the water down, and a filter before the water enters a storage tank or a recharge pit. Stored water can be used for gardening, cleaning and flushing toilets, which reduces the school's demand on the municipal supply. A recharge pit, on the other hand, lets the water soak into the ground and raises the water table over time.

Schools gain in other ways too. A working system is a live science lesson, since students can measure rainfall and calculate savings. It costs little to maintain if gutters are cleaned before every monsoon and the filter is checked each month. Schools that install such systems often report lower water bills.`, wl: [80, 120], model: `Title: Rainwater Harvesting in Schools

1. Why
   1.1 Roof = large free catchment
   1.2 800 sq m roof: thousands of litres lost in one shower
2. System parts
   2.1 Gutters
   2.2 Pipe
   2.3 Filter
   2.4 Tank or recharge pit
3. Uses
   3.1 Tank water: gardening, cleaning, toilets; less munic. supply
   3.2 Pit: raises water table
4. Other gains
   4.1 Live science lesson: measure rainfall, savings
   4.2 Low upkeep: clean gutters pre-monsoon; filter monthly
   4.3 Lower water bills

Key: sq m = square metres; munic. = municipal`, sol: 'Group the passage into why, parts, uses and other gains; keep points short; give a key.', scheme: SC_NOTES }));
Q('l_notes_sleep', L5({ t: 2, d: 3, c: 'application', stem: `Make notes on the passage in 80 to 120 words, using a suitable title, headings and sub-headings, and abbreviations with a key.

Teenagers need between eight and ten hours of sleep each night, yet many get less. Part of the reason is biological: during adolescence the body clock shifts, so teenagers feel sleepy later in the evening and wake later in the morning. When school starts early, this natural rhythm collides with the timetable.

The effects of too little sleep are wide. Concentration and memory suffer, so students find it harder to learn and recall what they study. Mood drops too, and tired teenagers are more likely to feel irritable or anxious. Over time, poor sleep is linked with weaker immunity and a greater risk of accidents, especially for those who ride or drive.

Simple habits can help. Going to bed at a fixed time, keeping screens out of the bedroom, avoiding strong tea or coffee late in the day and getting daylight in the morning all improve sleep. Some schools have moved their start time later by thirty to sixty minutes and found that students were more alert and attended more regularly.`, wl: [80, 120], model: `Title: Teenage Sleep: Need, Effects and Remedies

1. Need and causes
   1.1 8-10 hrs a night reqd; many get less
   1.2 Body clock shifts: sleepy late, wake late
   1.3 Early school clashes with this rhythm
2. Effects
   2.1 Poor concentration, memory
   2.2 Low mood: irritable, anxious
   2.3 Weak immunity; accident risk
3. Remedies
   3.1 Fixed bedtime
   3.2 No screens in bedroom
   3.3 No strong tea or coffee late
   3.4 Morning daylight
   3.5 Later school start (30-60 min): alert, regular attendance

Key: hrs = hours; reqd = required`, sol: 'Three headings: need and causes, effects, remedies; short points; key.', scheme: SC_NOTES }));
Q('l_notes_summary_mangrove', L5({ t: [2, 3], d: 4, c: 'application', stem: `Read the passage. (a) Make notes on it with a title, headings and sub-headings and abbreviations with a key (3 marks). (b) Write a summary of it in about 40 words (2 marks). Use about 80 to 120 words in all.

Mangroves are salt-tolerant trees that grow along tropical coasts, where rivers meet the sea. The Sundarbans, shared by India and Bangladesh, is the largest mangrove forest in the world. Their tangled roots stand above the mud and hold the soil together, so the coastline erodes more slowly. In a storm, the dense roots and branches slow the waves and reduce the force of storm surges, protecting the villages behind them. Mangroves also act as nurseries: the sheltered, shallow water among the roots gives young fish and prawns a safe place to grow, which supports local fishing. In addition, mangroves store carbon in their roots and in the mud beneath them.

Yet mangroves are disappearing. They have been cleared for shrimp farms, ports and housing, and polluted by waste. Conservation groups now replant mangroves, and local communities are paid for protecting them, because restoring mangroves is cheaper than rebuilding sea walls after storms.`, wl: [80, 120], model: `(a) Notes
Title: Mangroves: Uses and Threats
1. Features
   1.1 Salt-tolerant trees; tropical coasts
   1.2 Sund. = largest mangrove forest
2. Benefits
   2.1 Roots hold soil: less erosion
   2.2 Slow waves, storm surges
   2.3 Fish and prawn nurseries: fishing
   2.4 Store carbon
3. Threats: cleared for shrimp farms, ports, housing; waste
4. Remedy: replanting; paid community protection
Key: Sund. = Sundarbans

(b) Summary
Mangroves steady coasts, shield villages from storms, shelter young fish and store carbon, but clearing and pollution are destroying them. Replanting, with communities paid to protect them, is cheaper than rebuilding sea walls.`, sol: 'Notes: 3 marks (title, grouping, points, key). Summary: 2 marks (main ideas, brevity and own words).', scheme: [['Notes: suitable title and logical headings with sub-headings', 1], ['Notes: complete short points and an abbreviation key', 1], ['Notes: no copied sentences; accurate facts', 1], ['Summary: main ideas (benefits, threat, remedy)', 1], ['Summary: about 40 words, own words, no opinion', 1]] }));
Q('l_fix_notes', L5({ t: 2, d: 4, c: 'analysis', stem: `Below are a passage and a student's notes on it. (a) State three faults in the notes. (b) Rewrite the notes correctly. Use about 80 to 120 words in all.

**Passage.** India's postal network is the largest in the world by number of post offices, with offices in remote villages as well as cities. Besides letters and parcels, post offices offer savings accounts and small-savings schemes, and many sell insurance. In recent years the postal department has added digital services, such as tracking numbers for parcels and money transfer through mobile apps.

**Student's notes**
- India's postal network is the biggest in the whole world and it has offices in villages and cities
- Letters and parcels
- they also give savings accounts
- GPS: many services
- In recent years tracking no. for parcels
- Money transfer by apps; insurance sold`, wl: [80, 120], model: `(a) Faults: the notes copy full sentences instead of short points; there is no title and no headings, so related points are scattered (insurance sits beside digital services); and GPS is an invented abbreviation, with no key.

(b) Title: India Post
1. Network: largest in world; offices in villages and cities
2. Services
   2.1 Letters, parcels
   2.2 Savings a/cs, small-savings schemes
   2.3 Insurance
3. Digital
   3.1 Parcel tracking nos.
   3.2 Money transfer: mobile apps
Key: a/cs = accounts; nos. = numbers`, sol: 'Three faults: sentences, no title or headings, unexplained abbreviation. Then a corrected, grouped version with a key.', scheme: [['Three faults identified correctly', 2], ['Rewritten with title and logical headings', 1], ['Short points, accurate, no loss of facts', 1], ['Abbreviations explained in a key', 1]] }));
Q('l_compare_summaries', L5({ t: 3, d: 4, c: 'analysis', stem: `Read the passage and the two student summaries. (a) Say what is wrong with each summary. (b) Write your own summary in about 40 words. Use about 80 to 120 words in all.

**Passage.** Community radio stations are small, low-power broadcasters run by and for a local community. They are usually heard within a radius of about fifteen kilometres and broadcast in the local language. Programmes cover farming advice, weather warnings, health messages and folk songs recorded by villagers. Unlike commercial stations they are not run for profit, and volunteers from the area often present shows. In coastal villages such stations have broadcast cyclone warnings in time for fishermen to return. Their greatest strength is trust: listeners hear familiar voices speaking about familiar problems.

**Summary A.** Community radio stations are small, low-power broadcasters run by and for a local community, and they are usually heard within a radius of about fifteen kilometres and they broadcast in the local language and programmes cover farming advice, weather warnings, health messages and folk songs.

**Summary B.** Community radio is a wonderful idea that every village should have. It serves farmers, warns of cyclones and is run by volunteers in the local language.`, wl: [80, 120], model: `(a) Summary A copies the passage word for word, is too long and stops before the cyclone warnings and the point about trust. Summary B is short, but it begins with the summary-writer's own opinion, which does not belong in a summary, and it leaves out the idea of trust.

(b) Community radio stations are non-profit, volunteer-run broadcasters serving a small area in the local language. They carry farming advice, weather and health messages, and have even given cyclone warnings. Their strength is trust, as listeners hear familiar voices discussing familiar problems.`, sol: 'A: copied, too long, incomplete. B: opinion, misses trust. Own summary in fresh words, with the main ideas.', scheme: [['Fault in Summary A: copied, too long and incomplete', 1], ['Fault in Summary B: opinion and an omitted main idea', 1], ['Own summary covers purpose, content and trust', 1.5], ['Own summary in about 40 words, in own words', 1.5]] }));
Q('l_eval_phones', L5({ t: 1, d: 4, c: 'evaluation', stem: `Read the extract from a principal's annual message, then evaluate his argument in 80 to 120 words: say what is convincing, what is weak and what further evidence you would want.

*Since phones became common among our students three years ago, our average in the half-yearly examination has fallen from 71 to 64 per cent. Students use phones to chat in class, and they sleep late scrolling. A complete ban on phones on campus is the only sensible response. Parents who disagree are putting convenience before their children's future.*`, wl: [80, 120], model: `The argument has some force: the average has fallen by seven percentage points, and phones can distract in class and cut sleep. As proof, however, it is weak. The fall followed phones, but harder papers or changes of teacher could also explain it, and the principal compares no phone users with non-users. The remark about disagreeing parents attacks people instead of answering their view. I would want results by phone use, figures from other years and a trial of limited rules, such as phones kept in bags during lessons, before accepting a total ban.`, sol: 'A judgement with both sides: seven-point fall and possible distraction; weaknesses: correlation, no comparison, personal attack; further evidence.', scheme: [['What is convincing: the fall and the plausible effects', 1], ['Weaknesses: cause not proved; no comparison group', 2], ['The unfair remark about parents identified', 1], ['Further evidence or a reasoned alternative', 1]] }));
